css:
@import url("https://fonts.googleapis.com/css2?family=Funnel+Display:wght@600;800&family=Funnel+Sans:wght@400;500;600&display=swap");
:root{--gp:#5B3FD1;--gp2:#4630A8;--lm:#F9E45B;--lv:#F3F0FF;--ink:#1C1633;--gr:#5D5875;--ln:#E4DFF5;--h:"Funnel Display",system-ui,sans-serif;--b:"Funnel Sans",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.6;color:var(--ink);background:#fff}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:800;margin:0;line-height:1.05;letter-spacing:-.015em}
.wrap{max-width:1200px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--lm);padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--lm);outline-offset:2px}
.nav{display:flex;justify-content:space-between;align-items:center;height:78px;position:relative}.logo{font-family:var(--h);font-weight:800;font-size:26px;text-decoration:none;display:flex;gap:8px;align-items:center;color:var(--gp)}
.menu{display:flex;gap:24px;list-style:none;margin:0;padding:0;font-weight:500;align-items:center}.menu a{text-decoration:none}.menu .cta{background:var(--ink);color:#fff;padding:9px 18px;border-radius:30px}
.burger{display:none;background:none;border:2px solid var(--gp);color:var(--gp);width:44px;height:40px;border-radius:12px;font-size:20px;cursor:pointer}
.hero{background:var(--lv);border-radius:36px;margin:0 16px;padding:60px 0}.hero .wrap{display:grid;grid-template-columns:1fr 1.05fr;gap:40px;align-items:center}
.hero h1{font-size:clamp(44px,5.6vw,76px)}.hero p{font-size:19px;color:var(--gr);margin:20px 0 26px;max-width:30em}
.btn{display:inline-block;background:var(--gp);color:#fff;text-decoration:none;font:600 17px var(--b);padding:14px 24px;border-radius:30px;border:0;cursor:pointer}.btn.y{background:var(--lm);color:var(--ink)}
.row{display:flex;flex-wrap:wrap;gap:12px}
.dash{background:#fff;border-radius:26px;padding:22px;box-shadow:0 30px 60px rgba(91,63,209,.18);display:grid;grid-template-columns:1fr 1fr;gap:14px}
.dash h2{grid-column:1/-1;font-size:22px;display:flex;justify-content:space-between;align-items:center}.dash h2 span{font-family:var(--b);font-weight:500;font-size:14px;color:var(--gr)}
.tile{background:var(--lv);border-radius:18px;padding:16px}.tile small{display:block;color:var(--gr);font-size:13px}.tile b{font-family:var(--h);font-size:30px}
.ring{display:flex;gap:12px;align-items:center}.ring svg{flex:none}
.streak{display:flex;gap:5px;margin-top:8px}.streak i{flex:1;height:26px;border-radius:6px;background:#DCD5F7}.streak i.on{background:var(--gp)}.streak i.td{background:var(--lm);outline:2px solid var(--gp)}
.mine{grid-column:1/-1}.mine ul{list-style:none;padding:0;margin:8px 0 0}.mine li{display:grid;grid-template-columns:1fr 90px 42px;gap:10px;align-items:center;padding:8px 0;border-top:1px solid var(--ln);font-size:15px}
.mine .pb{height:8px;background:var(--lv);border-radius:8px;overflow:hidden}.mine .pb i{display:block;height:100%;background:var(--gp)}.mine .pc{font-weight:600;text-align:right;font-size:14px}
.mine .em{color:var(--gr);font-size:15px;padding:8px 0}
section{padding:84px 0}.sh{display:flex;justify-content:space-between;align-items:flex-end;flex-wrap:wrap;gap:14px;margin-bottom:24px}.sh h2{font-size:clamp(34px,4.4vw,56px)}.sh p{color:var(--gr);margin:6px 0 0}
.bar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-bottom:14px}.srch{flex:1 1 260px}.srch input{width:100%;font:17px var(--b);padding:13px 18px;border:2px solid var(--ln);border-radius:30px;color:var(--ink)}
.bar select{font:16px var(--b);padding:12px 14px;border:2px solid var(--ln);border-radius:30px;background:#fff;color:var(--ink)}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:22px}.chips button{font:600 15px var(--b);background:var(--lv);border:0;border-radius:30px;padding:9px 16px;cursor:pointer;color:var(--ink)}.chips button[aria-pressed=true]{background:var(--ink);color:#fff}
.cnt{color:var(--gr);margin:0 0 16px}
.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}
.cc{border:2px solid var(--ln);border-radius:22px;overflow:hidden;display:flex;flex-direction:column;background:#fff}
.cv{aspect-ratio:16/10;position:relative;display:grid;place-items:center;overflow:hidden}.cv svg{width:44%;height:auto}
.cv .lv{position:absolute;left:12px;top:12px;background:rgba(255,255,255,.9);border-radius:20px;padding:2px 10px;font-size:13px;font-weight:600}
.cc .c{padding:16px 18px 18px;display:flex;flex-direction:column;flex:1}.cc h3{font-size:20px;line-height:1.2}.cc .by{font-size:14px;color:var(--gr);margin:4px 0 10px}
.cc .mt{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:14px;color:var(--gr);margin-bottom:14px;flex:1}.cc .mt b{color:#B7791F}
.cc .ft{display:flex;justify-content:space-between;align-items:center;gap:10px}.cc .pr{font-family:var(--h);font-weight:800;font-size:20px}
.cc button{font:600 15px var(--b);background:var(--gp);color:#fff;border:0;border-radius:30px;padding:9px 16px;cursor:pointer}.cc button[aria-pressed=true]{background:var(--lm);color:var(--ink)}
.none{grid-column:1/-1;background:var(--lv);border-radius:22px;padding:30px;text-align:center}
.any{background:var(--ink);color:#fff;border-radius:36px;margin:0 16px}.any .wrap{display:grid;grid-template-columns:1fr 1fr;gap:50px;align-items:center}
.any h2{font-size:clamp(34px,4.4vw,54px)}.any p{color:#C9C3E4}.any img{border-radius:26px;width:100%;aspect-ratio:4/3;object-fit:cover}
.any ul{list-style:none;padding:0;margin:20px 0 0}.any li{padding:10px 0 10px 34px;position:relative;border-top:1px solid #332B55}.any li:before{content:"";position:absolute;left:0;top:14px;width:20px;height:20px;border-radius:50%;background:var(--lm)}
.pl .pg{display:grid;grid-template-columns:1fr 1fr;gap:20px;max-width:860px}.pp{border:2px solid var(--ln);border-radius:26px;padding:30px}.pp.pro{background:var(--gp);color:#fff;border-color:var(--gp)}
.pp h3{font-size:28px}.pp .pr{font-family:var(--h);font-weight:800;font-size:54px;margin:10px 0}.pp .pr small{font:500 16px var(--b)}.pp ul{padding-left:20px;margin:0 0 22px}.pp li{margin:6px 0}.pp.pro .btn{background:var(--lm);color:var(--ink)}
footer{padding:30px 0;font-size:15px;color:var(--gr)}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:1060px){.cards{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media (max-width:900px){.hero .wrap,.any .wrap{grid-template-columns:1fr}.cards{grid-template-columns:1fr 1fr}.pl .pg{grid-template-columns:1fr}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:78px;left:0;right:0;background:#fff;flex-direction:column;align-items:flex-start;padding:18px 22px;z-index:30;box-shadow:0 10px 20px rgba(0,0,0,.06)}.menu.open{display:flex}.hero,.any{margin:0 8px;border-radius:24px}.dash{grid-template-columns:1fr}.mine li{grid-template-columns:1fr 60px 40px}}
@media (max-width:520px){.cards{grid-template-columns:1fr}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);
const IC={Business:'<path d="M10 40h44M16 40V26h8v14M28 40V18h8v22M40 40V30h8v10" stroke="#fff" stroke-width="4" fill="none"/>',Tech:'<path d="M22 20 10 32l12 12M42 20l12 12-12 12" stroke="#fff" stroke-width="5" fill="none" stroke-linecap="round"/>',Design:'<circle cx="24" cy="26" r="12" fill="none" stroke="#fff" stroke-width="4"/><rect x="30" y="30" width="20" height="20" fill="none" stroke="#fff" stroke-width="4"/>','Life skills':'<path d="M32 50s-18-10-18-24a10 10 0 0 1 18-6 10 10 0 0 1 18 6c0 14-18 24-18 24z" fill="none" stroke="#fff" stroke-width="4"/>'};
const COL={Business:"#1F8A70",Tech:"#5B3FD1",Design:"#E4572E",'Life skills':"#D6336C"};
const C=[["Excel for everyday work","Business","Beginner",0,3.5,4.8,41200,"Hannah Moss"],["Managing your first team","Business","Intermediate",39,5,4.7,18300,"Owen Price"],["Negotiation basics","Business","Beginner",29,2.5,4.6,12900,"Grace Lin"],["Python for beginners","Tech","Beginner",0,8,4.9,63500,"Arjun Rao"],["SQL in a weekend","Tech","Beginner",29,4,4.8,27100,"Lena Fischer"],["Build a website with HTML and CSS","Tech","Beginner",0,6,4.7,48800,"Sam Carter"],["JavaScript beyond the basics","Tech","Advanced",49,9,4.8,15200,"Arjun Rao"],["Figma from zero","Design","Beginner",29,4.5,4.8,22400,"Mia Torres"],["Colour and type for non-designers","Design","Beginner",0,2,4.6,19800,"Mia Torres"],["UX research methods","Design","Intermediate",39,6,4.7,9700,"Tom Becker"],["Money basics: budgets and saving","Life skills","Beginner",0,2,4.9,35600,"Rita Gomez"],["Public speaking without panic","Life skills","Intermediate",29,3,4.8,21300,"Owen Price"]];
const mine=new Map([["Python for beginners",42],["Money basics: budgets and saving",75]]);let cat='';
function cover(c){return`<div class="cv" style="background:${COL[c[1]]};background-image:radial-gradient(circle at 85% 20%,rgba(255,255,255,.22) 0 22%,transparent 23%),radial-gradient(circle at 10% 90%,rgba(0,0,0,.12) 0 28%,transparent 29%)"><span class="lv">${c[2]}</span><svg viewBox="0 0 64 64" aria-hidden="true">${IC[c[1]]}</svg></div>`}
function cards(){const q=$('q').value.trim().toLowerCase(),lv=$('lvl').value,p=$('prc').value,s=$('srt').value;
let r=C.filter(c=>(!cat||c[1]===cat)&&(!lv||c[2]===lv)&&(!p||(p==='free'?c[3]===0:c[3]>0))&&(!q||(c[0]+' '+c[7]).toLowerCase().includes(q)));
r.sort((a,b)=>s==='rate'?b[5]-a[5]:s==='short'?a[4]-b[4]:b[6]-a[6]);$('cnt').textContent=`${r.length} course${r.length===1?'':'s'}`;
$('cards').innerHTML=r.length?r.map(c=>{const on=mine.has(c[0]);return`<article class="cc">${cover(c)}<div class="c"><h3>${c[0]}</h3><p class="by">with ${c[7]}</p><div class="mt"><span><b>★ ${c[5]}</b></span><span>${c[4]} hours</span><span>${(c[6]/1000).toFixed(1)}k learners</span></div><div class="ft"><span class="pr">${c[3]?'$'+c[3]:'Free'}</span><button type="button" data-n="${c[0]}" aria-pressed="${on}">${on?'Enrolled ✓':'Enrol'}</button></div></div></article>`}).join(''):'<p class="none">No courses match. Try a different word or clear a filter.</p>'}
function dash(){const L=[...mine];$('mine').innerHTML=L.length?L.map(([n,p])=>`<li><span>${n}</span><span class="pb"><i style="width:${p}%"></i></span><span class="pc">${p}%</span></li>`).join(''):'<li class="em">No courses yet. Enrol below to get started.</li>';
const m=Math.min(60,24+L.length*9);$('wg').textContent=`${m} of 60`;$('rg').style.strokeDashoffset=94.2*(1-m/60)}
$('cards').onclick=e=>{const b=e.target.closest('button');if(!b)return;const n=b.dataset.n;mine.has(n)?mine.delete(n):mine.set(n,0);cards();dash()};
['q','lvl','prc','srt'].forEach(i=>$(i).addEventListener('input',cards));
$('chips').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('chips').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));cat=b.dataset.c;cards()};
const D=['M','T','W','T','F','S','S'],td=(new Date().getDay()+6)%7;$('stk').innerHTML=D.map((d,i)=>`<i class="${i===td?'td':'on'}"></i>`).join('');$('dd').textContent=new Date().toLocaleDateString('en-US',{weekday:'long'});
cards();dash();
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
